/* ==========================================================================
   Pixel Grocery Budget Tracker Styles
   Cohesive 4-Color Palette: Dark Slate, Mint Cream, Golden Sand, Crimson Red
   ========================================================================== */

:root {
  --color-bg: #2d3748;
  --color-card-bg: #ffffff;
  --color-border: #1a202c;
  --color-accent: #2b6cb0;
  --color-accent-hover: #2c5282;
  --color-danger: #c53030;
  --color-danger-bg: #fed7d7;
  --color-success: #22543d;
  --color-success-bg: #c6f6d5;
  --color-text-dark: #1a202c;
  --color-text-muted: #4a5568;
  --pixel-border-width: 4px;
  --pixel-shadow: 4px 4px 0px #1a202c;
  --pixel-shadow-sm: 2px 2px 0px #1a202c;
  --pixel-shadow-pressed: 1px 1px 0px #1a202c;
}

/* Mandatory hidden utility rule */
[hidden] {
  display: none !important;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--color-bg);
  /* Pixel patterned grid background */
  background-image: 
    linear-gradient(45deg, #252e3d 25%, transparent 25%),
    linear-gradient(-45deg, #252e3d 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #252e3d 75%),
    linear-gradient(-45deg, transparent 75%, #252e3d 75%);
  background-size: 16px 16px;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0px;
  font-family: "Courier New", Courier, monospace, monospace;
  font-size: 16px;
  color: var(--color-text-dark);
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 24px 12px;
}

.app-container {
  width: 100%;
  max-width: 620px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* Header */
.app-header {
  text-align: center;
  background: #f7fafc;
  border: var(--pixel-border-width) solid var(--color-border);
  box-shadow: var(--pixel-shadow);
  padding: 16px;
}

.pixel-title {
  font-size: 1.75rem;
  letter-spacing: 2px;
  color: var(--color-text-dark);
  margin-bottom: 4px;
  text-transform: uppercase;
}

.pixel-subtitle {
  font-size: 1rem;
  font-weight: bold;
  color: var(--color-accent);
  letter-spacing: 1px;
}

/* Pixel Card Container */
.pixel-box {
  background: var(--color-card-bg);
  border: var(--pixel-border-width) solid var(--color-border);
  box-shadow: var(--pixel-shadow);
  padding: 18px;
}

.section-title {
  font-size: 1.15rem;
  font-weight: bold;
  margin-bottom: 14px;
  border-bottom: var(--pixel-border-width) solid var(--color-border);
  padding-bottom: 6px;
  text-transform: uppercase;
}

/* Labels & Inputs */
.pixel-label {
  display: block;
  font-size: 1rem;
  font-weight: bold;
  margin-bottom: 6px;
  color: var(--color-text-dark);
}

input[type="text"],
input[type="number"] {
  width: 100%;
  font-family: inherit;
  font-size: 1rem;
  padding: 10px 12px;
  color: var(--color-text-dark);
  background-color: #f7fafc;
  border: var(--pixel-border-width) solid var(--color-border);
  outline: none;
  box-shadow: inset 2px 2px 0px rgba(0, 0, 0, 0.1);
}

input:focus {
  background-color: #ffffff;
  border-color: var(--color-accent);
}

.input-row {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.input-action-group {
  display: flex;
  gap: 10px;
}

.input-action-group input {
  flex: 1;
}

.form-grid {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 14px;
}

.form-group-duo {
  display: flex;
  gap: 12px;
}

.form-group-duo .form-group {
  flex: 1;
}

/* Buttons */
.pixel-btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  cursor: pointer;
  background-color: #edf2f7;
  color: var(--color-text-dark);
  border: var(--pixel-border-width) solid var(--color-border);
  box-shadow: var(--pixel-shadow-sm);
  padding: 10px 16px;
  text-transform: uppercase;
  transition: transform 0.05s ease, box-shadow 0.05s ease;
  outline: none;
}

.pixel-btn:hover {
  background-color: #e2e8f0;
}

.pixel-btn:focus-visible {
  border-color: var(--color-accent);
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: var(--pixel-shadow-pressed);
}

.pixel-btn-primary {
  width: 100%;
  background-color: #bee3f8;
}

.pixel-btn-primary:hover {
  background-color: #90cdf4;
}

.pixel-btn-small {
  font-size: 0.85rem;
  padding: 4px 8px;
}

.pixel-btn-danger {
  background-color: #fed7d7;
  color: var(--color-danger);
  padding: 6px 10px;
}

.pixel-btn-danger:hover {
  background-color: #feb2b2;
}

/* Summary Grid */
.summary-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.summary-tile {
  background-color: #edf2f7;
  border: 3px solid var(--color-border);
  padding: 10px 6px;
  text-align: center;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
}

.tile-label {
  font-size: 0.85rem;
  font-weight: bold;
  color: var(--color-text-muted);
}

.tile-value {
  font-size: 1.15rem;
  font-weight: bold;
}

/* Over-budget warning state */
.is-over-budget .tile-value,
.is-over-budget.tile-value,
.over-budget-text {
  color: var(--color-danger) !important;
}

.summary-tile.is-over-budget {
  background-color: var(--color-danger-bg);
  border-color: var(--color-danger);
}

.budget-alert {
  margin-top: 12px;
  padding: 10px;
  background-color: var(--color-danger);
  color: #ffffff;
  font-weight: bold;
  text-align: center;
  border: 3px solid var(--color-border);
  letter-spacing: 1px;
  animation: pixelPulse 1s infinite alternate;
}

@keyframes pixelPulse {
  0% { opacity: 0.9; transform: scale(1); }
  100% { opacity: 1; transform: scale(1.02); }
}

/* Cart List */
.list-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
}

.list-header .section-title {
  margin-bottom: 0;
  border-bottom: none;
  padding-bottom: 0;
}

.grocery-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.grocery-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 12px;
  border: 3px solid var(--color-border);
  background-color: #f7fafc;
  box-shadow: 2px 2px 0px rgba(0, 0, 0, 0.15);
}

.item-details {
  display: flex;
  flex-direction: column;
  gap: 2px;
  word-break: break-word;
}

.item-name-text {
  font-size: 1.05rem;
  font-weight: bold;
}

.item-calculation-text {
  font-size: 0.9rem;
  color: var(--color-text-muted);
}

.item-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.item-subtotal {
  font-size: 1.1rem;
  font-weight: bold;
}

.empty-msg {
  text-align: center;
  padding: 18px;
  font-style: italic;
  color: var(--color-text-muted);
}

/* Responsiveness */
@media (max-width: 480px) {
  .summary-grid {
    grid-template-columns: 1fr;
  }

  .form-group-duo {
    flex-direction: column;
  }

  .grocery-item {
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
  }

  .item-actions {
    width: 100%;
    justify-content: space-between;
  }
}

(function () {
  'use strict';

  // State
  var state = {
    budget: 0.00,
    items: []
  };

  // DOM References
  var budgetForm = document.getElementById('budget-form');
  var budgetInput = document.getElementById('budget-input');
  var budgetDisplay = document.getElementById('budget-display');

  var itemForm = document.getElementById('item-form');
  var itemNameInput = document.getElementById('item-name');
  var itemPriceInput = document.getElementById('item-price');
  var itemQtyInput = document.getElementById('item-qty');

  var totalWrapper = document.getElementById('total-wrapper');
  var totalDisplay = document.getElementById('total-display');
  var remainingWrapper = document.getElementById('remaining-wrapper');
  var remainingDisplay = document.getElementById('remaining-display');
  var budgetAlert = document.getElementById('budget-alert');

  var groceryList = document.getElementById('grocery-list');
  var emptyMessage = document.getElementById('empty-message');
  var clearAllBtn = document.getElementById('clear-all-btn');

  // Format currency with standard 2 decimal places
  function formatCurrency(amount) {
    return '$' + amount.toFixed(2);
  }

  // Calculate summary figures with float safety
  function calculateTotals() {
    var totalSpent = state.items.reduce(function (sum, item) {
      return sum + (item.price * item.quantity);
    }, 0);

    // Round to 2 decimals to prevent binary float inaccuracies
    totalSpent = Math.round(totalSpent * 100) / 100;
    var remaining = Math.round((state.budget - totalSpent) * 100) / 100;

    return {
      totalSpent: totalSpent,
      remaining: remaining,
      isOverBudget: state.budget > 0 && totalSpent > state.budget
    };
  }

  // Render updated summary numbers and styles
  function renderSummary() {
    var totals = calculateTotals();

    budgetDisplay.textContent = formatCurrency(state.budget);
    totalDisplay.textContent = formatCurrency(totals.totalSpent);
    remainingDisplay.textContent = formatCurrency(totals.remaining);

    if (totals.isOverBudget) {
      totalWrapper.classList.add('is-over-budget');
      totalDisplay.classList.add('over-budget-text');
      remainingWrapper.classList.add('is-over-budget');
      remainingDisplay.classList.add('over-budget-text');
      budgetAlert.removeAttribute('hidden');
    } else {
      totalWrapper.classList.remove('is-over-budget');
      totalDisplay.classList.remove('over-budget-text');
      remainingWrapper.classList.remove('is-over-budget');
      remainingDisplay.classList.remove('over-budget-text');
      budgetAlert.setAttribute('hidden', '');
    }
  }

  // Render the grocery list
  function renderList() {
    groceryList.innerHTML = '';

    if (state.items.length === 0) {
      emptyMessage.removeAttribute('hidden');
    } else {
      emptyMessage.setAttribute('hidden', '');

      state.items.forEach(function (item) {
        var li = document.createElement('li');
        li.className = 'grocery-item';

        var detailsDiv = document.createElement('div');
        detailsDiv.className = 'item-details';

        var nameSpan = document.createElement('span');
        nameSpan.className = 'item-name-text';
        nameSpan.textContent = item.name;

        var calcSpan = document.createElement('span');
        calcSpan.className = 'item-calculation-text';
        calcSpan.textContent = item.quantity + ' x ' + formatCurrency(item.price);

        detailsDiv.appendChild(nameSpan);
        detailsDiv.appendChild(calcSpan);

        var actionsDiv = document.createElement('div');
        actionsDiv.className = 'item-actions';

        var subtotalSpan = document.createElement('span');
        subtotalSpan.className = 'item-subtotal';
        subtotalSpan.textContent = formatCurrency(item.price * item.quantity);

        var deleteBtn = document.createElement('button');
        deleteBtn.type = 'button';
        deleteBtn.className = 'pixel-btn pixel-btn-danger';
        deleteBtn.setAttribute('aria-label', 'Remove ' + item.name);
        deleteBtn.textContent = 'DEL';
        deleteBtn.dataset.id = item.id;

        actionsDiv.appendChild(subtotalSpan);
        actionsDiv.appendChild(deleteBtn);

        li.appendChild(detailsDiv);
        li.appendChild(actionsDiv);

        groceryList.appendChild(li);
      });
    }

    renderSummary();
  }

  // Event: Set Budget
  budgetForm.addEventListener('submit', function (e) {
    e.preventDefault();
    var enteredBudget = parseFloat(budgetInput.value);
    if (isNaN(enteredBudget) || enteredBudget < 0) {
      alert('Please enter a valid non-negative budget.');
      return;
    }
    state.budget = Math.round(enteredBudget * 100) / 100;
    renderSummary();
  });

  // Event: Add Item
  itemForm.addEventListener('submit', function (e) {
    e.preventDefault();

    var name = itemNameInput.value.trim();
    var price = parseFloat(itemPriceInput.value);
    var quantity = parseInt(itemQtyInput.value, 10);

    if (!name) {
      itemNameInput.focus();
      return;
    }
    if (isNaN(price) || price < 0) {
      itemPriceInput.focus();
      return;
    }
    if (isNaN(quantity) || quantity <= 0) {
      itemQtyInput.focus();
      return;
    }

    var newItem = {
      id: Date.now().toString(36) + Math.random().toString(36).substr(2, 5),
      name: name,
      price: Math.round(price * 100) / 100,
      quantity: quantity
    };

    state.items.push(newItem);
    renderList();

    // Reset inputs
    itemNameInput.value = '';
    itemPriceInput.value = '';
    itemQtyInput.value = '1';
    itemNameInput.focus();
  });

  // Event: Item List Click (Delegation for delete button)
  groceryList.addEventListener('click', function (e) {
    var target = e.target;
    if (target && target.tagName === 'BUTTON' && target.dataset.id) {
      var itemId = target.dataset.id;
      state.items = state.items.filter(function (item) {
        return item.id !== itemId;
      });
      renderList();
    }
  });

  // Event: Clear All Items
  clearAllBtn.addEventListener('click', function () {
    if (state.items.length === 0) return;
    if (confirm('Clear all grocery items from cart?')) {
      state.items = [];
      renderList();
    }
  });

  // Initial render
  renderList();
})();
